css:
.bl { display: grid; gap: var(--os-space-xl); align-items: center; }
.bl__eyebrow { margin: 0 0 var(--os-space-xs); font-family: var(--os-font-label); font-size: var(--os-type-eyebrow-font-size); letter-spacing: var(--os-type-eyebrow-letter-spacing); text-transform: uppercase; color: var(--os-eyebrow-color, var(--os-color-accent)); }
.bl__title { margin: 0 0 var(--os-space-sm); font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); font-size: var(--os-type-h1-font-size); line-height: var(--os-type-h1-line-height); color: var(--os-color-heading); text-wrap: balance; }
.bl__intro { max-width: 30em; font-size: var(--os-type-lead-font-size); line-height: var(--os-type-lead-line-height); color: var(--os-color-text); }
.bl__intro p { margin: 0; }
.bl__stage { padding: var(--os-space-sm) var(--os-space-sm) var(--os-space-md); }
.bl__card { position: relative; background: var(--os-color-text); color: var(--os-color-background); border-radius: var(--os-radius-image, 14px); padding: var(--os-space-xl) var(--os-space-lg) var(--os-space-lg); transform: rotate(-1.5deg); box-shadow: 10px 10px 0 var(--os-color-ochre); transition: transform 0.7s var(--os-motion-ease, ease-out), opacity 0.5s ease-out; }
.bl__card::before { content: ''; position: absolute; top: 14px; left: 50%; width: 16px; height: 16px; margin-left: -8px; border-radius: 50%; background: var(--os-color-background); }
.bl__top { display: flex; justify-content: flex-end; margin-bottom: var(--os-space-xs); }
.bl__stamp { font-family: var(--os-font-label); font-size: var(--os-type-eyebrow-font-size); letter-spacing: var(--os-type-eyebrow-letter-spacing); text-transform: uppercase; color: var(--os-color-background); border: 2px solid var(--os-color-accent); border-radius: 999px; padding: 2px 12px; }
.bl__cardtitle { margin: 0 0 var(--os-space-sm); padding-bottom: var(--os-space-xs); border-bottom: 2px dashed var(--os-color-background); font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); font-size: var(--os-type-h2-font-size); line-height: 1.1; }
.bl__rows { list-style: none; margin: 0; padding: 0; }
.bl__row { display: flex; align-items: flex-end; gap: var(--os-space-sm); padding: 10px 0; }
.bl__item { flex: none; font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); font-size: var(--os-type-h4-font-size); line-height: 1.15; }
.bl__from { flex: 1; display: flex; align-items: flex-end; gap: 8px; min-width: 0; }
.bl__fromlbl { flex: none; font-family: var(--os-font-label); font-size: var(--os-type-small-font-size); text-transform: uppercase; letter-spacing: 0.08em; color: var(--os-color-accent); }
.bl__blank { flex: 1; min-width: 40px; height: 0; margin-bottom: 5px; border-bottom: 2px solid var(--os-color-background); transform-origin: left center; }
.bl__caption { margin: var(--os-space-sm) 0 0; padding-top: var(--os-space-xs); border-top: 2px dashed var(--os-color-background); font-family: var(--os-font-label); font-size: var(--os-type-small-font-size); color: var(--os-color-background); }
.bl--js .bl__card { opacity: 0; transform: translateY(32px) rotate(-5deg); }
.bl--js.is-in .bl__card { opacity: 1; transform: rotate(-1.5deg); }
.bl--js .bl__row { opacity: 0; transform: translateY(10px); }
.bl--js .bl__blank { transform: scaleX(0); }
.bl--js.is-in .bl__row { opacity: 1; transform: none; transition: opacity 0.24s ease-out, transform 0.24s ease-out; transition-delay: calc(0.45s + var(--i, 0) * 0.16s); }
.bl--js.is-in .bl__blank { transform: scaleX(1); transition: transform 0.4s ease-out; transition-delay: calc(0.65s + var(--i, 0) * 0.16s); }
@media (min-width: 768px) { .bl { grid-template-columns: 1fr 1.1fr; gap: var(--os-space-2xl); } .bl__card { padding: var(--os-space-xl) var(--os-space-xl) var(--os-space-lg); } }
@media (prefers-reduced-motion: reduce) { .bl__card, .bl__row, .bl__blank { transition: none !important; } }

js:
const bl = root.querySelector('.bl');
const card = root.querySelector('[data-bl-card]');
if (!bl || !card || ctx.reducedMotion) return;
Array.prototype.slice.call(root.querySelectorAll('[data-bl-row]')).forEach((row, i) => { row.style.setProperty('--i', String(i)); });
bl.classList.add('bl--js');
const io = new IntersectionObserver((entries) => {
  if (entries[0].isIntersecting) {
    bl.classList.add('is-in');
    io.disconnect();
  }
}, { threshold: 0.3 });
io.observe(card);
